"use client";

import "./spinner.css";
import type React from "react";
import { cn } from "tailwind-variants";

import { SpinnerContext } from "./spinner.context";
import { spinnerVariants, type SpinnerVariants } from "./spinner.variants";

export type SpinnerProps = SpinnerVariants & React.ComponentProps<"svg">;

export const SpinnerRoot = ({
  className,
  size,
  variant,
  ...props
}: SpinnerProps) => {
  const slots = spinnerVariants({ size, variant });

  return (
    <SpinnerContext.Provider value={{ slots }}>
      <svg
        role="status"
        aria-label="Loading"
        className={cn(slots.root(), className)}
        fill="none"
        viewBox="0 0 24 24"
        {...props}
      >
        <circle
          className="opacity-25"
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeWidth="4"
        />
        <path
          className="opacity-75"
          fill="currentColor"
          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
        />
      </svg>
    </SpinnerContext.Provider>
  );
};

export const Spinner = SpinnerRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const spinnerVariants = tv({
  slots: {
    root: "spinner",
  },
  variants: {
    size: {
      sm: { root: "spinner--sm" },
      md: { root: "spinner--md" },
      lg: { root: "spinner--lg" },
      xl: { root: "spinner--xl" },
    },
    variant: {
      default: { root: "" },
      muted: { root: "spinner--muted" },
      primary: { root: "spinner--primary" },
    },
  },
  defaultVariants: {
    size: "md",
    variant: "default",
  },
});

export type SpinnerVariants = VariantProps<typeof spinnerVariants>;

"use client";

import { createContext, useContext } from "react";

import { spinnerVariants } from "./spinner.variants";

export type SpinnerContext = {
  slots: ReturnType<typeof spinnerVariants>;
};

export const SpinnerContext = createContext<SpinnerContext | null>(null);

export const useSpinnerContext = () => {
  const context = useContext(SpinnerContext);
  return context ?? { slots: spinnerVariants() };
};

.spinner {
  @apply inline-block animate-spin text-current shrink-0;
}

.spinner--sm {
  @apply h-4 w-4;
}

.spinner--md {
  @apply h-6 w-6;
}

.spinner--lg {
  @apply h-8 w-8;
}

.spinner--xl {
  @apply h-12 w-12;
}

.spinner--muted {
  @apply text-muted-foreground;
}

.spinner--primary {
  @apply text-primary;
}

import { Spinner, SpinnerRoot } from "./spinner";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/spinner/content.md
 */
export const SpinnerContainer = {
  Root: SpinnerRoot,
};

export { Spinner, SpinnerRoot };

export type { SpinnerProps } from "./spinner";
export { SpinnerContext, useSpinnerContext } from "./spinner.context";
export { type SpinnerVariants, spinnerVariants } from "./spinner.variants";
